    "Her ay gelen sular, siparişin tarihindeki fiyatla hesaplanır. Ay sonunda gelen faturanın tutarını aya tıklayıp girin; tutmazsa kırmızı görünür.": "Water delivered each month is valued at the price on the order date. At month end, click the month and enter the invoice amount; if it does not match, it shows in red.",
    "Her fatura ya da sayaç okuma belgesi bir kayıttır. Satıra tıklayıp düzeltin; doğalgazda girilen birimin karşılığı kendiliğinden hesaplanır.": "Each invoice or meter reading document is one record. Click a row to edit; for natural gas, the equivalent of the unit entered is calculated automatically.",
