    "Başlangıç tarihinden itibaren, elle girilmeyen her iş gününe (hafta içi, resmî tatil hariç) bu kadar öğle sayılır. Bir güne elle sayı girilirse o geçerli olur. 0 yazılırsa otomatik doldurma kapanır; izin gibi dönemler için Genel Bakış › “Geçici sayı”.": "С указанной даты программа подставляет это количество обедов в каждый рабочий день без ручного ввода. Выходные и официальные праздники исключаются. Введённое вручную число имеет приоритет. Укажите 0, чтобы отключить автозаполнение. Для временных изменений, например на время отпуска, используйте «Обзор → Временное количество».",
