    "Hepsi girildi": "Всё внесено",
    "Her ay gelen sular, siparişin tarihindeki fiyatla hesaplanır. Ay sonunda gelen faturanın tutarını aya tıklayıp girin; tutmazsa kırmızı görünür.": "Доставленная за месяц вода рассчитывается по цене на дату заказа. В конце месяца выберите нужный месяц и введите сумму счёта. Расхождение выделяется красным.",
    "Her fatura ya da sayaç okuma belgesi bir kayıttır. Satıra tıklayıp düzeltin; doğalgazda girilen birimin karşılığı kendiliğinden hesaplanır.": "Каждому счёту или документу с показаниями счётчика соответствует одна запись. Нажмите на строку, чтобы изменить её. Для природного газа пересчёт единиц выполняется автоматически.",
    "Her kartta bir sonraki adıma tek dokunuşla geçin. Yalnızca “Yola çıktı” stoktan düşer.": "Переводите отправление на следующий этап прямо из карточки. Запас уменьшается только при статусе «Отправлено».",
    "Her kartta bir sonraki aşamaya tek dokunuşla geçin. Satış, “Yolda” olduğu andan itibaren rapora girer.": "Следующий этап можно выбрать прямо в карточке. Продажа входит в отчёт, как только отгрузка получает статус «В пути».",
    "Her partiden ne kadar satıldığı ve kimlere gittiği. Partiler sevkiyatlardan derlenir; sevkiyatı olmayan parti görünmez.": "Здесь видно, сколько продано из каждой партии и каким клиентам. Список составляется по отгрузкам. Партии без отгрузок не показаны.",
    "Herkes işte sayılır; yalnızca izin, rapor, gelmeme ve fazla mesai girilir.": "По умолчанию все сотрудники считаются присутствующими. Вносите только отпуск, больничный, отсутствие и сверхурочные.",
