    "Nereden doldurdunuz?": "Из какой тары разливали?",
    "İsotanktan dolduysa isotank numarasını yazın. Büyük numuneden dolduysa kaynak kabı seçin; kalan miktar açık kap olarak izlenir.": "При розливе из танк-контейнера укажите его номер. При розливе из большой ёмкости с образцом выберите её как источник. Остаток будет учтён как объём в открытой ёмкости.",
