    "Raftan dokunarak ekleyin; her dokunuş bir şişe ekler.": "Выберите образцы на полке. Каждое нажатие добавляет одну бутылку.",
    "Şişe etiketleri, sample no ve belgeler": "Этикетки бутылок, номера образцов и документы",
    "Her şişenin sample numarasını (örn. 0608261/1) yazın ve Canva’dan çıkardığınız etiketi yükleyin; her kalemin CoA’sını altına ekleyin. İsterseniz atlayıp sonra gönderi kaydından eklersiniz.": "Введите номер каждой бутылки (например, 0608261/1) и загрузите этикетку из Canva. Ниже прикрепите протокол анализа (CoA) по каждой позиции. Файлы можно добавить позже в карточке отправки.",
    "Nasıl gönderiliyor?": "Как отправляете?",
