    "Sadece “Yola çıktı” stoktan düşer. Diğerlerinde şişeler rafta ayrılmış (rezerve) görünür. Sorumlu ve tarih zorunludur.": "Остаток уменьшается при статусе «Отправлено». До отправки бутылки отмечены как зарезервированные. Ответственный и дата обязательны.",
